// shader_common_glsl.h's text, generated by the build (nx_shaders.cmake).
extern "C" const char g_xrGlslHeader[];
extern "C" const size_t g_xrGlslHeaderSize;

namespace renut::nxs {

namespace {
// Bump when the translation changes in a way the header's text does not show (shader_recompiler.cpp).
constexpr uint64_t kTranslatorVersion = 14;  // 14 (2026-11-15): the previous-frame textures of a vertex shader (MotionVectorPass); 13: as 11 again (12, 2026-11-15, made the motion vectors a run-time switch as in the FNXF games: +2.9 ms of GPU a frame at the default settings, taken back); 11: motion from pixel shaders with two colour outputs, the previous constants' range (2026-11-15); 10: no pred-select pass on the Switch (2026-11-12)
                                            // 4: the old deko3d passes (2026-10-23); 5: MotionVectorPass (2026-11-06);
                                            // 6: the bound 2D fetches' descriptor word (dynamic resolution, 2026-11-07)
}  // namespace

uint64_t Fnv1a64(const void *data, size_t size) {
  const auto *p = static_cast<const uint8_t *>(data);
  uint64_t h = 0xcbf29ce484222325ull;
  for (size_t i = 0; i < size; i++) {
    h ^= p[i];
    h *= 0x100000001b3ull;
  }
  return h;
}

std::string_view GlslHeader() { return std::string_view(g_xrGlslHeader, g_xrGlslHeaderSize); }

uint64_t TranslatorTag() {
  static const uint64_t tag = [] {
    uint64_t h = Fnv1a64(g_xrGlslHeader, g_xrGlslHeaderSize);
    h ^= kTranslatorVersion * 0x9E3779B97F4A7C15ull;
    return h;
  }();
  return tag;
}

size_t ContainerSize(const uint8_t *container, size_t available) {
  if (available < sizeof(ShaderContainer))
    return 0;
  const auto *c = reinterpret_cast<const ShaderContainer *>(container);
  if ((c->flags & 0xFFFFFF00u) != 0x102A1100u)
    return 0;
  const uint32_t vsize = c->virtualSize, psize = c->physicalSize;
  if (vsize < sizeof(ShaderContainer) || vsize > 0x10000 || psize == 0 || psize > 0x100000)
    return 0;
  const size_t size = size_t(vsize) + psize;
  return size <= available ? size : 0;
}

namespace {

inline bool IdentStart(char c) { return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_'; }
inline bool IdentChar(char c) { return IdentStart(c) || (c >= '0' && c <= '9'); }

// Calls fn(name) for every identifier in text[begin, end) (comments included: a name only a comment mentions keeps
// its function, which costs nothing but the trim it misses). No allocation.
template <typename Fn>
void ForEachIdentifier(const std::string &text, size_t begin, size_t end, Fn &&fn) {
  const char *d = text.data();
  for (size_t i = begin; i < end;) {
    if (IdentStart(d[i]) && (i == 0 || !IdentChar(d[i - 1]))) {
      size_t j = i + 1;
      while (j < end && IdentChar(d[j]))
        ++j;
      fn(std::string_view(d + i, j - i));
      i = j;
    }
    else {
      ++i;
    }
  }
}

}  // namespace

// tw2de (2026-10-21): the shader with only the functions it can reach. Every translation carries the whole of
// shader_common_glsl.h (27 KB, ~90 functions), and uam parsed, checked and optimised all of them for every shader and
// every variant: about a third of a compile. Only function definitions go (a body at depth 0 after ')'): the
// preprocessor lines, macros, uniforms, structs and declarations stay as they are, so every #ifdef and every variant's
// specialization constant works as before. A name kept keeps all its overloads.
std::string TrimUnusedFunctions(const std::string &glsl) {
  struct Function {
    size_t begin, end;  // the line its name is on .. after its closing brace (and that line's newline)
    std::string_view name;
  };
  std::vector<Function> functions;
  functions.reserve(256);  // shader_common_glsl.h has ~90, the shader's own a few: no regrowth
  const size_t n = glsl.size();
  int depth = 0;
  size_t open = 0;            // the '{' a depth-0 function body starts at
  std::string_view pending_name;  // that function's name
  size_t pending_begin = 0;
  bool line_start = true;
  for (size_t i = 0; i < n; ++i) {
    const char c = glsl[i];
    if (c == '/' && i + 1 < n && glsl[i + 1] == '/') {  // a line comment
      while (i < n && glsl[i] != '\n')
        ++i;
      line_start = true;
      continue;
    }
    if (c == '/' && i + 1 < n && glsl[i + 1] == '*') {  // a block comment
      const size_t e = glsl.find("*/", i + 2);
      i = e == std::string::npos ? n : e + 1;
      continue;
    }
    if (line_start && c == '#') {  // a preprocessor line (with its continuations)
      while (i < n && !(glsl[i] == '\n' && glsl[i - 1] != '\\'))
        ++i;
      continue;
    }
    if (c == '\n') {
      line_start = true;
      continue;
    }
    if (c != ' ' && c != '\t' && c != '\r')
      line_start = false;
    if (c == '{') {
      if (depth == 0) {
        // A function body: the last character before it (spaces and newlines aside) is ')'.
        size_t k = i;
        while (k > 0 && (glsl[k - 1] == ' ' || glsl[k - 1] == '\t' || glsl[k - 1] == '\n' || glsl[k - 1] == '\r'))
          --k;
        pending_name = {};
        if (k > 0 && glsl[k - 1] == ')') {
          // Its '(' and the name before it.
          int paren = 0;
          size_t p = k - 1;
          for (;; --p) {
            if (glsl[p] == ')')
              ++paren;
            else if (glsl[p] == '(' && --paren == 0)
              break;
            if (p == 0)
              break;
          }
          size_t e = p;
          while (e > 0 && (glsl[e - 1] == ' ' || glsl[e - 1] == '\t'))
            --e;
          size_t b = e;
          while (b > 0 && IdentChar(glsl[b - 1]))
            --b;
          if (b < e && IdentStart(glsl[b])) {
            pending_name = std::string_view(glsl.data() + b, e - b);
            size_t line = glsl.rfind('\n', b);
            pending_begin = line == std::string::npos ? 0 : line + 1;
          }
        }
        open = i;
      }
      ++depth;
      continue;
    }
    if (c == '}') {
      if (--depth == 0 && !pending_name.empty()) {
        size_t end = i + 1;
        if (end < n && glsl[end] == '\n')
          ++end;
        functions.push_back({pending_begin, end, pending_name});
        pending_name = {};
      }
      if (depth < 0)
        return glsl;  // not text this understands: left whole
      continue;
    }
  }
  (void)open;
  if (depth != 0 || functions.empty())
    return glsl;

  // The functions by name (sorted: a lookup per identifier is a binary search over ~90, no hashing, no allocation).
  std::vector<std::pair<std::string_view, uint32_t>> by_name;
  by_name.reserve(functions.size());
  for (uint32_t i = 0; i < functions.size(); ++i)
    by_name.emplace_back(functions[i].name, i);
  std::sort(by_name.begin(), by_name.end());
  std::vector<bool> kept(functions.size(), false);
  std::vector<uint32_t> todo;
  todo.reserve(functions.size());  // each function goes in once at most
  auto use = [&](std::string_view name) {
    auto it = std::lower_bound(by_name.begin(), by_name.end(), std::make_pair(name, uint32_t(0)));
    for (; it != by_name.end() && it->first == name; ++it)  // every overload
      if (!kept[it->second]) {
        kept[it->second] = true;
        todo.push_back(it->second);
      }
  };
  // The roots: every name outside the function definitions (main's caller is the GPU: main is one).
  use("main");
  size_t at = 0;
  for (const Function &f : functions) {
    ForEachIdentifier(glsl, at, f.begin, use);
    at = f.end;
  }
  ForEachIdentifier(glsl, at, n, use);
  // What the used functions reach.
  while (!todo.empty()) {
    const Function &f = functions[todo.back()];
    todo.pop_back();
    ForEachIdentifier(glsl, f.begin, f.end, use);
  }
  std::string out;
  out.reserve(glsl.size());
  at = 0;
  for (size_t i = 0; i < functions.size(); ++i) {
    if (kept[i])
      continue;
    out.append(glsl, at, functions[i].begin - at);
    at = functions[i].end;
  }
  out.append(glsl, at, std::string::npos);
  return out;
}

namespace {

// One `layout(location = N) in|out TYPE NAME;` line of the translator's interface declarations.
struct InterfaceDecl {
  size_t begin = 0, end = 0;  // the line, with its newline
  uint32_t location = 0;
  std::string type, name;
};

std::vector<InterfaceDecl> FindInterface(const std::string &glsl, size_t limit, std::string_view dir) {
  std::vector<InterfaceDecl> decls;
  static constexpr std::string_view head = "layout(location = ";
  for (size_t p = 0; (p = glsl.find(head, p)) != std::string::npos && p < limit;) {
    const size_t line_end = glsl.find('\n', p);
    if (line_end == std::string::npos)
      break;
    if (p != 0 && glsl[p - 1] != '\n') {  // only at the start of a line
      p = line_end;
      continue;
    }
    InterfaceDecl d;
    d.begin = p;
    d.end = line_end + 1;
    size_t q = p + head.size();
    while (q < line_end && glsl[q] >= '0' && glsl[q] <= '9')
      d.location = d.location * 10 + uint32_t(glsl[q++] - '0');
    // ") in TYPE NAME;"
    const std::string tail = glsl.substr(q, line_end - q);
    const std::string prefix = ") " + std::string(dir) + " ";
    if (tail.compare(0, prefix.size(), prefix) == 0 && tail.size() > prefix.size() && tail.back() == ';') {
      const size_t sp = tail.find(' ', prefix.size());
      if (sp != std::string::npos) {
        d.type = tail.substr(prefix.size(), sp - prefix.size());
        d.name = tail.substr(sp + 1, tail.size() - sp - 2);
        if (d.location < 32 && !d.name.empty() && d.name.find(' ') == std::string::npos)
          decls.push_back(d);
      }
    }
    p = line_end;
  }
  return decls;
}

// How often each identifier occurs in text[begin, end).
std::unordered_map<std::string_view, uint32_t> CountIdentifiers(const std::string &text, size_t begin, size_t end) {
  std::unordered_map<std::string_view, uint32_t> counts;
  ForEachIdentifier(text, begin, end, [&](std::string_view name) { ++counts[name]; });
  return counts;
}

// Replaces every whole-identifier occurrence of 'name' in text[begin, end) with 'with'; returns the new end.
size_t ReplaceIdentifier(std::string &text, size_t begin, size_t end, const std::string &name, const std::string &with) {
  std::string out;
  out.reserve(end - begin + 64);
  size_t last = begin;
  for (size_t i = begin; i + name.size() <= end;) {
    if (text.compare(i, name.size(), name) == 0 && (i == 0 || !IdentChar(text[i - 1])) &&
        (i + name.size() >= text.size() || !IdentChar(text[i + name.size()])) && (i == 0 || text[i - 1] != '.')) {
      out.append(text, last, i - last);
      out += with;
      i += name.size();
      last = i;
    }
    else {
      ++i;
    }
  }
  out.append(text, last, end - last);
  text.replace(begin, end - begin, out);
  return begin + out.size();
}

}  // namespace

// tw2de (2026-10-23): the old pipeline's bound textures (tools/deko3d_glsl.py, game shaders) and its txq pass
// (tools/deko3d_glsl_opt.py). The translator's 2D and cube fetches name their texture and sampler by SharedConstants
// words (sN_Texture2DDescriptorIndex = RENUT_SHARED_UINT(byte offset)); each distinct (kind, slot) becomes binding k of
// the stage, `texb=k:<texture word>:<sampler word>` in the tw2de-dk line, which plume_deko3d binds per draw with the
// handle the bindless form makes ((texture & 0xFFFFF) | (sampler & 0xFFF00000)). A 2D binding's level-0 size, which the
// fetches with a texel offset and the bilinear weights divide or multiply by, is entry k of the texture size buffer
// (UBO binding 3, plume fills it from the descriptor's view: txq=<mask>) in pixel shaders when constant 908 is not 0
// (tw2de_deko3d_txq_constants), else a query.
std::string BoundTexturePass(const std::string &glsl, bool pixel) {
  const size_t main_at = glsl.find("\nvoid main()\n{\n");
  const size_t dk = glsl.find("// tw2de-dk ");
  if (main_at == std::string::npos || dk == std::string::npos || dk > main_at)
    return glsl;
  // The words of each sampler slot: "#define sN_<Kind>DescriptorIndex RENUT_SHARED_UINT(offset)".
  auto word_of = [&](const std::string &macro) -> int {
    const std::string key = "#define " + macro + " RENUT_SHARED_UINT(";
    const size_t p = glsl.find(key);
    if (p == std::string::npos || p > main_at)
      return -1;
    return std::atoi(glsl.c_str() + p + key.size());
  };
  struct Binding {
    bool cube;
    int slot, texture_word, sampler_word;
  };
  std::vector<Binding> bindings;
  struct Kind {
    std::string_view func;
    bool cube;
  };
  static constexpr Kind kinds[] = {{"tfetch2D(", false},       {"tfetch2DLevel(", false}, {"getWeights2D(", false},
                                   {"getCompTexLod2D(", false}, {"tfetchCube(", true},     {"tfetchCubeLevel(", true},
                                   {"getCompTexLodCube(", true}};
  std::string body = glsl.substr(main_at);
  std::string out;
  out.reserve(body.size());
  size_t i = 0;
  while (i < body.size()) {
    // The next 's' that starts "sN_Texture" right after one of the functions' '('.
    bool done = false;
    for (const Kind &k : kinds) {
      if (body.compare(i, k.func.size(), k.func) != 0 || (i > 0 && IdentChar(body[i - 1])))
        continue;
      const size_t a = i + k.func.size();
      // "sN_Texture2DDescriptorIndex, sN_SamplerDescriptorIndex, "
      size_t q = a;
      if (q >= body.size() || body[q] != 's')
        break;
      ++q;
      int slot = 0;
      size_t digits = q;
      while (q < body.size() && body[q] >= '0' && body[q] <= '9')
        slot = slot * 10 + (body[q++] - '0');
      if (q == digits)
        break;
      const std::string tex = fmt::format("s{}_Texture{}DescriptorIndex", slot, k.cube ? "Cube" : "2D");
      const std::string smp = fmt::format("s{}_SamplerDescriptorIndex", slot);
      const std::string args = tex + ", " + smp + ", ";
      if (body.compare(a, args.size(), args) != 0)
        break;
      const int tw = word_of(tex), sw = word_of(smp);
      if (tw < 0 || sw < 0)
        break;
      size_t index = bindings.size();
      for (size_t b = 0; b < bindings.size(); ++b)
        if (bindings[b].cube == k.cube && bindings[b].slot == slot)
          index = b;
      if (index == bindings.size()) {
        if (bindings.size() >= 32)
          break;
        bindings.push_back({k.cube, slot, tw, sw});
      }
      out.append(k.func);
      // tw2de (2026-11-07, dynamic resolution): the 2D fetches also take the texture's descriptor index word
      // (shader_common_glsl.h renutDrsUv: a dynamic-resolution texture's level).
      const bool with_word = k.func == "tfetch2D(" || k.func == "tfetch2DLevel(";
      out += k.cube       ? fmt::format("dk_tex_b{}, ", index)
             : with_word ? fmt::format("dk_tex_b{0}, DK_TEX_SIZE_{0}, DK_TEX_WORD_{0}, ", index)
                         : fmt::format("dk_tex_b{0}, DK_TEX_SIZE_{0}, ", index);
      i = a + args.size();
      done = true;
      break;
    }
    if (!done)
      out += body[i++];
  }
  if (bindings.empty())
    return glsl;
  std::string decl = "// tw2de: bound textures (BoundTexturePass)\n";
  uint32_t txq_mask = 0;
  if (pixel)
    decl += "#ifndef SPIRV_CROSS_CONSTANT_ID_908\n#define SPIRV_CROSS_CONSTANT_ID_908 1u\n#endif\n"
            "const uint g_fnxf_xiii_lrTxq = SPIRV_CROSS_CONSTANT_ID_908;\n"
            "layout(binding = 3, std140) uniform type_DkTexSize\n{\n    uvec4 v[64];\n} g_UboTexSize;\n";
  std::string texb;
  for (size_t b = 0; b < bindings.size(); ++b) {
    const Binding &x = bindings[b];
    decl += fmt::format("layout(binding = {}) uniform {} dk_tex_b{};\n", b, x.cube ? "samplerCube" : "sampler2D", b);
    if (!x.cube) {
      decl += fmt::format("#define DK_TEX_WORD_{} RENUT_SHARED_UINT({})\n", b, x.texture_word);  // tw2de (2026-11-07)
      if (pixel) {
        decl += fmt::format("#define DK_TEX_SIZE_{0} ((g_fnxf_xiii_lrTxq != 0u) ? ivec2(g_UboTexSize.v[{0}u].xy) : "
                            "textureSize(dk_tex_b{0}, 0))\n", b);
        txq_mask |= 1u << b;
      }
      else {
        decl += fmt::format("#define DK_TEX_SIZE_{0} textureSize(dk_tex_b{0}, 0)\n", b);
      }
    }
    texb += fmt::format("{}{}:{}:{}", b ? "," : "", b, x.texture_word, x.sampler_word);
  }
  std::string text = glsl.substr(0, main_at) + "\n" + decl + out.substr(1);
  // The tw2de-dk line: texb=, and for the size buffer txq= and UBO bit 3.
  const size_t line_end = text.find('\n', dk);
  std::string line = text.substr(dk, line_end - dk);
  if (txq_mask) {
    const size_t u = line.find("ubo=0x");
    if (u != std::string::npos) {
      const size_t e = line.find(' ', u);
      const uint32_t ubo = uint32_t(std::strtoul(line.c_str() + u + 6, nullptr, 16)) | 8u;
      line.replace(u, e - u, fmt::format("ubo=0x{:x}", ubo));
    }
    line += fmt::format(" txq=0x{:x}", txq_mask);
  }
  line += " texb=" + texb;
  text.replace(dk, line_end - dk, line);
  return text;
}

// tw2de (2026-10-23): the stage interface passes of the old deko3d pipeline (tools/deko3d_glsl_opt.py: vsout, vszero,
// pszero, earlyz), for the translator's GLSL. The constants are the ones render/pipeline.cpp and plume_deko3d give:
//  - pixel shaders declare only the inputs they read (the translator declares all 24), so plume_deko3d's input mask is
//    what the shader reads; each read input is zero where constant 906 says its vertex shader writes it as zero
//    (pszero), and a shader without a depth output gets constant 909's early depth test (earlyz);
//  - vertex shaders record the outputs they write as zero only (a `// tw2de-vszero=0x...` line, vszero), and write
//    each output only where constant 905 (the locations the pipeline's pixel shader reads) has its bit (vsout): main
//    runs as before into the same variables, which are copied to the outputs at its end.
std::string StageInterfacePasses(const std::string &glsl, bool pixel) {
  const size_t main_at = glsl.find("\nvoid main()\n{\n");
  if (main_at == std::string::npos)
    return glsl;
  std::string text = glsl;
  if (pixel) {
    std::vector<InterfaceDecl> ins = FindInterface(text, main_at, "in");
    auto counts = CountIdentifiers(text, main_at, text.size());
    // tw2de (2026-11-10): which inputs are used, decided here: counts' keys point into text, which the
    // replacements below change (a lookup after them could miss a used input and erase its declaration: FF XIII-2's
    // "iTexCoord0 undeclared" shaders).
    std::vector<InterfaceDecl> used;
    std::vector<bool> in_use(ins.size(), false);
    for (size_t i = 0; i < ins.size(); i++)
      if (counts.count(std::string_view(ins[i].name))) {
        used.push_back(ins[i]);
        in_use[i] = true;
      }
    counts.clear();
    // The body first (later offsets), then the declarations, back to front.
    size_t body_begin = main_at, body_end = text.size();
    for (const InterfaceDecl &d : used)
      body_end = ReplaceIdentifier(text, body_begin, body_end, d.name, "DK_IN_" + d.name);
    std::string decl = "// tw2de (pszero): an input its vertex shader writes as zero (constant 906) is zero\n"
                       "#ifndef SPIRV_CROSS_CONSTANT_ID_906\n#define SPIRV_CROSS_CONSTANT_ID_906 0u\n#endif\n"
                       "const uint g_fnxf_xiii_lrPsZeroIn = SPIRV_CROSS_CONSTANT_ID_906;\n";
    for (const InterfaceDecl &d : used)
      decl += fmt::format("#define DK_IN_{0} (((g_fnxf_xiii_lrPsZeroIn & {1}u) != 0u) ? {2}(0.0) : {0})\n", d.name,
                          1u << d.location, d.type);
    if (text.find("gl_FragDepth") == std::string::npos && text.find("discard") != std::string::npos)
      decl += "// tw2de (earlyz): constant 909 = 1 (a draw that writes neither depth nor stencil) tests depth first\n"
              "#ifndef SPIRV_CROSS_CONSTANT_ID_909\n#define SPIRV_CROSS_CONSTANT_ID_909 0u\n#define DK_EARLY_Z 0\n"
              "#else\n#define DK_EARLY_Z 1\n#endif\n#if DK_EARLY_Z\nlayout(early_fragment_tests) in;\n#endif\n";
    text.insert(main_at + 1, decl);
    for (size_t i = ins.size(); i-- > 0;)
      if (!in_use[i])
        text.erase(ins[i].begin, ins[i].end - ins[i].begin);
    return text;
  }
  std::vector<InterfaceDecl> outs = FindInterface(text, main_at, "out");
  if (outs.empty())
    return text;
  // vszero: an output whose only occurrence in main is the translator's `NAME = vecN(0.0);` / `= 0.0;`.
  uint32_t zero_mask = 0;
  {
    auto counts = CountIdentifiers(text, main_at, text.size());
    for (const InterfaceDecl &d : outs) {
      auto it = counts.find(std::string_view(d.name));
      if (it == counts.end() || it->second != 1)
        continue;
      const std::string zero = "\t" + d.name + " = " + (d.type == "float" ? std::string("0.0") : d.type + "(0.0)") + ";\n";
      if (text.find(zero, main_at) != std::string::npos)
        zero_mask |= 1u << d.location;
    }
  }
  // vsout: main into fnxf_xiii_lrVsMain, the outputs plain variables, copied to the real outputs (dk_o_NAME) at the end.
  std::string copies = "// tw2de (vsout): only the outputs the pipeline's pixel shader reads (constant 905)\n"
                       "#ifndef SPIRV_CROSS_CONSTANT_ID_905\n#define SPIRV_CROSS_CONSTANT_ID_905 4294967295u\n#endif\n"
                       "const uint g_fnxf_xiii_lrVsOutputs = SPIRV_CROSS_CONSTANT_ID_905;\n";
  std::string writes;
  for (const InterfaceDecl &d : outs)
    writes += fmt::format("    if ((g_fnxf_xiii_lrVsOutputs & {}u) != 0u)\n        dk_o_{} = {};\n", 1u << d.location, d.name,
                          d.name);
  text.replace(main_at, std::string_view("\nvoid main()\n{\n").size(),
               copies + "\nvoid fnxf_xiii_lrVsMain()\n{\n");
  text += "\nvoid main()\n{\n    fnxf_xiii_lrVsMain();\n" + writes + "}\n";
  for (auto it = outs.rbegin(); it != outs.rend(); ++it)
    text.replace(it->begin, it->end - it->begin,
                 fmt::format("{1} {2};\nlayout(location = {0}) out {1} dk_o_{2};\n", it->location, it->type, it->name));
  if (zero_mask) {
    // After the #version line and the tw2de-dk line (plume_deko3d finds it anywhere).
    size_t nl = text.find('\n');
    if (nl != std::string::npos && text.compare(nl + 1, 13, "// tw2de-dk ") == 0)
      nl = text.find('\n', nl + 1);
    text.insert(nl + 1, fmt::format("// tw2de-vszero=0x{:x}\n", zero_mask));
  }
  return text;
}

// tw2de (2026-11-06): the end of the function body whose '{' is at 'open' (after its '}'), npos when unbalanced.
// Line comments are skipped (the translator writes no braces in strings).
size_t BodyEnd(const std::string &text, size_t open) {
  int depth = 0;
  for (size_t i = open; i < text.size(); ++i) {
    const char c = text[i];
    if (c == '/' && i + 1 < text.size() && text[i + 1] == '/') {
      while (i < text.size() && text[i] != '\n')
        ++i;
      continue;
    }
    if (c == '{')
      ++depth;
    else if (c == '}' && --depth == 0)
      return i + 1;
  }
  return std::string::npos;
}

// tw2de (2026-11-06): motion vectors for FSR 3 (render/draw.cpp, Motion*). Every game shader gets them, switched per
// draw by SharedConstants' g_FnxfMotion (shader_common_glsl.h), so one translation serves both FSR 3 and the rest:
//  - vertex shaders (after StageInterfacePasses: fnxf_xiii_lrVsMain and main): with bit 0 the body runs first as a copy that
//    reads its float constants from UBO 4 (the same draw's constants of the previous frame, which the renderer binds),
//    and the position it gives is the previous one; the current position, before the jitter (bit 2: g_FnxfJitter times
//    w), and the previous one go out at locations 25 and 26 (x, y, w);
//  - pixel shaders with one colour output: main into fnxf_xiii_lrPsMain, then with bit 0 the motion (previous minus current
//    position, in normalized device coordinates) to colour output 1, which the renderer binds only for the scene's
//    opaque draws (a write mask on its target 1 for the others); with bit 1 (a diagnostic) the motion as the colour.
// Locations 25 and 26 follow the translator's 0..24 (interpolators, point coordinate, point size).
constexpr uint32_t kMotionCurLocation = 25, kMotionPrevLocation = 26;

std::string MotionVectorPass(const std::string &glsl, bool pixel) {
  std::string text = glsl;
  if (pixel) {
    const size_t main_at = text.find("\nvoid main()\n{\n");
    if (main_at == std::string::npos)
      return glsl;
    // One colour output only: the scene's shaders (the motion goes to output 1).
    // TW2 (2026-11-15): or two (TW2's G-buffer pass): the motion goes to the output after them.
    if (text.find("layout(location = 0) out vec4 oC0;") == std::string::npos ||
        text.find(" out vec4 oC2;") != std::string::npos || text.find(" out vec4 oC3;") != std::string::npos)
      return glsl;
    const uint32_t motion_location = text.find(" out vec4 oC1;") != std::string::npos ? 2u : 1u;
    const size_t open = main_at + std::string_view("\nvoid main()\n").size();
    if (BodyEnd(text, open) == std::string::npos)
      return glsl;
    text.replace(main_at, std::string_view("\nvoid main()\n{\n").size(), "\nvoid fnxf_xiii_lrPsMain()\n{\n");
    const std::string decl = fmt::format(
        "// tw2de (MotionVectorPass): the motion of this pixel's surface for FSR 3\n"
        "layout(location = {}) in vec3 iFnxfMotionCur;\n"
        "layout(location = {}) in vec3 iFnxfMotionPrev;\n"
        "layout(location = {}) out vec4 oFnxfMotion;\n",
        kMotionCurLocation, kMotionPrevLocation, motion_location);
    text.insert(main_at + 1, decl);
    text += "\nvoid main()\n{\n"
            "    fnxf_xiii_lrPsMain();\n"
            "    uint motion = (g_renutWordFx & 4u) != 0u ? g_FnxfMotion : 0u;  // constant 914 bit 2\n"
            "    if ((motion & 3u) != 0u)\n"
            "    {\n"
            "        vec2 cur = iFnxfMotionCur.xy / iFnxfMotionCur.z;\n"
            "        vec2 prev = iFnxfMotionPrev.xy / iFnxfMotionPrev.z;\n"
            "        vec2 mv = prev - cur;\n"
            "        oFnxfMotion = vec4(mv, 0.0, 1.0);\n"
            "        if ((motion & 2u) != 0u)\n"
            "            oC0 = vec4(clamp(abs(mv) * 25.0, 0.0, 1.0), (mv.x < 0.0 ? 0.5 : 0.0) + (mv.y < 0.0 ? 0.5 : 0.0),"
            " oC0.w);\n"
            "    }\n"
            "}\n";
    return text;
  }
  static constexpr std::string_view head = "\nvoid fnxf_xiii_lrVsMain()\n{\n";
  const size_t vs_at = text.find(head);
  const size_t gc = text.find("#define g_C(INDEX) g_UboVertex.v[");
  const size_t main_at = text.find("\nvoid main()\n{\n    fnxf_xiii_lrVsMain();\n");
  if (vs_at == std::string::npos || gc == std::string::npos || main_at == std::string::npos || main_at < vs_at)
    return glsl;
  const size_t open = vs_at + head.size() - 2;  // the '{'
  const size_t end = BodyEnd(text, open);
  if (end == std::string::npos || end > main_at)
    return glsl;
  // The copy: the body with g_C( as g_CPrev( (whole identifiers; the translator reads every float constant through it).
  std::string copy = text.substr(vs_at, end - vs_at);
  copy.replace(0, head.size(), "\nvoid fnxf_xiii_lrVsMainPrev()\n{\n");
  {
    std::string out;
    out.reserve(copy.size() + 1024);
    for (size_t i = 0; i < copy.size();) {
      if (copy.compare(i, 4, "g_C(") == 0 && (i == 0 || !IdentChar(copy[i - 1]))) {
        out += "g_CPrev(";
        i += 4;
      }
      else {
        out += copy[i++];
      }
    }
    copy = std::move(out);
  }
  // TW2 (2026-11-15, the user: with FSR 3.1 the NPCs' moving arms ghost): the previous position of a skinned vertex.
  // The game skins in its vertex shaders, four bones' rows a vertex from a texture (768x256 floats at vertex fetch
  // slot 16; two such textures filled in turn, a frame each), so the copy has to read LAST frame's texture. Each 2D
  // texture the shader has bound (BoundTexturePass: dk_tex_bK, texb=K:<texture word>:<sampler word>) that the body
  // reads gets a second binding, dk_tex_prev_bK, which the copy reads instead; its texture word is the 3D word of the
  // same fetch slot (SharedConstants texture_indices[1][slot]: 128 bytes after the 2D one, free in a draw whose
  // texture there is 2D), where render/draw.cpp puts last frame's texture (MotionPrepareLocked), or this frame's.
  std::string prev_decl, prev_texb;
  {
    const size_t dk0 = text.find("// tw2de-dk ");
    const size_t line_end0 = dk0 == std::string::npos ? std::string::npos : text.find('\n', dk0);
    const size_t tb = dk0 == std::string::npos ? std::string::npos : text.find(" texb=", dk0);
    if (tb != std::string::npos && tb < line_end0) {
      const size_t value_at = tb + 6;
      const std::string value = text.substr(value_at, std::min(text.find(' ', value_at), line_end0) - value_at);
      struct Bound {
        unsigned k, texture_word, sampler_word;
      };
      std::vector<Bound> bound;
      for (size_t q = 0; q < value.size();) {
        Bound b{};
        if (std::sscanf(value.c_str() + q, "%u:%u:%u", &b.k, &b.texture_word, &b.sampler_word) != 3)
          break;
        bound.push_back(b);
        const size_t comma = value.find(',', q);
        if (comma == std::string::npos)
          break;
        q = comma + 1;
      }
      unsigned next = unsigned(bound.size());
      for (const Bound &b : bound) {
        const std::string name = fmt::format("dk_tex_b{}", b.k);
        if (b.texture_word >= 128 || text.find("uniform sampler2D " + name + ";") == std::string::npos)
          continue;  // not a 2D texture's word
        const std::string prev_name = fmt::format("dk_tex_prev_b{}", b.k);
        std::string out;
        out.reserve(copy.size() + 256);
        bool any = false;
        for (size_t i = 0; i < copy.size();) {
          if (copy.compare(i, name.size(), name) == 0 && (i == 0 || !IdentChar(copy[i - 1])) &&
              (i + name.size() >= copy.size() || !IdentChar(copy[i + name.size()]))) {
            out += prev_name;
            i += name.size();
            any = true;
          }
          else {
            out += copy[i++];
          }
        }
        if (!any)
          continue;  // the body does not read it
        copy = std::move(out);
        prev_decl += fmt::format("layout(binding = {}) uniform sampler2D {};\n", next, prev_name);
        prev_texb += fmt::format(",{}:{}:{}", next, 128 + b.texture_word, b.sampler_word);
        ++next;
      }
    }
  }
  // main: the previous position first, then the body as it was; the copies to the outputs follow as before.
  const size_t call_at = main_at + std::string_view("\nvoid main()\n{\n").size();
  const std::string call = "    fnxf_xiii_lrVsMain();\n";
  const std::string motion_main =
      "    uint motion = (g_renutWordFx & 4u) != 0u ? g_FnxfMotion : 0u;  // constant 914 bit 2\n"
      "    vec4 fnxfPrevPos = vec4(0.0);\n"
      "    if ((motion & 1u) != 0u)\n"
      "    {\n"
      "        fnxf_xiii_lrVsMainPrev();\n"
      "        fnxfPrevPos = gl_Position;\n"
      "    }\n"
      "    fnxf_xiii_lrVsMain();\n"
      "    vec4 fnxfCurPos = gl_Position;\n"
      "    if ((motion & 1u) == 0u)\n"
      "        fnxfPrevPos = fnxfCurPos;\n"
      "    if ((motion & 4u) != 0u)\n"
      "        gl_Position.xy += g_FnxfJitter * gl_Position.w;\n" +
      fmt::format("    if ((g_fnxf_xiii_lrVsOutputs & {}u) != 0u)\n        dk_o_fnxfMotionCur = fnxfCurPos.xyw;\n"
                  "    if ((g_fnxf_xiii_lrVsOutputs & {}u) != 0u)\n        dk_o_fnxfMotionPrev = fnxfPrevPos.xyw;\n",
                  1u << kMotionCurLocation, 1u << kMotionPrevLocation);
  text.replace(call_at, call.size(), motion_main);
  text.insert(end, copy);
  // The declarations: the previous constants' block (UBO 4), its g_CPrev, the two outputs; and UBO bit 4 in the
  // tw2de-dk line, so plume_deko3d binds the renderer's slot 4 for this shader.
  const std::string decl = fmt::format(
      "// tw2de (MotionVectorPass): the previous frame's float constants of this draw, and the positions for FSR 3\n"
      "layout(binding = 4, std140) uniform RenutUboPrevVertex {{ vec4 v[257]; }} g_UboPrevVertex;\n"
      "#define g_CPrev(INDEX) ((uint(INDEX) - (g_FnxfPrevRange & 0xFFFFu)) < (g_FnxfPrevRange >> 16u) ? "
      "g_UboPrevVertex.v[min(uint(INDEX), 256u)] : g_C(INDEX))\n"
      "layout(location = {}) out vec3 dk_o_fnxfMotionCur;\n"
      "layout(location = {}) out vec3 dk_o_fnxfMotionPrev;\n",
      kMotionCurLocation, kMotionPrevLocation);
  const size_t gc_end = text.find('\n', gc);
  if (gc_end == std::string::npos)
    return glsl;
  text.insert(gc_end + 1, decl + prev_decl);
  const size_t dk = text.find("// tw2de-dk ");
  if (dk != std::string::npos) {
    const size_t line_end = text.find('\n', dk);
    const size_t u = text.find("ubo=0x", dk);
    if (u != std::string::npos && u < line_end) {
      const size_t e = std::min(text.find(' ', u), line_end);
      const uint32_t ubo = uint32_t(std::strtoul(text.c_str() + u + 6, nullptr, 16)) | 0x10u;
      text.replace(u, e - u, fmt::format("ubo=0x{:x}", ubo));
    }
    // TW2 (2026-11-15): the previous-frame textures' bindings, after the shader's own.
    if (!prev_texb.empty()) {
      const size_t line_end2 = text.find('\n', dk);
      const size_t tb = text.find(" texb=", dk);
      if (tb != std::string::npos && tb < line_end2)
        text.insert(std::min(text.find(' ', tb + 6), line_end2), prev_texb);
    }
  }
  return text;
}

bool Translate(const uint8_t *container, size_t size, TranslatedShader &out) {
  if (ContainerSize(container, size) != size)
    return false;
  const auto *c = reinterpret_cast<const ShaderContainer *>(container);
  if (uint32_t(c->shaderOffset) + sizeof(Shader) > uint32_t(c->virtualSize))
    return false;

  thread_local ShaderRecompiler recompiler;
  recompiler = {};
  recompiler.glsl = true;
  recompiler.recompile(container, GlslHeader());

  // tw2de (2026-11-10): XenosRecomp declares r0..r31; FF XIII-2 has shaders using r32 and up (Xenos gives a
  // shader up to 128). The ones used are declared after r31, zeroed as the others (only in those shaders: every
  // other shader's GLSL, and so its compiled key, stays as it was).
  if (const size_t r31 = recompiler.out.find("\tfloat4 r31 = "); r31 != std::string::npos) {
    const size_t line_end = recompiler.out.find('\n', r31);
    if (line_end != std::string::npos) {
      bool used[128] = {};
      bool any = false;
      ForEachIdentifier(recompiler.out, line_end, recompiler.out.size(), [&](std::string_view name) {
        if (name.size() < 3 || name.size() > 4 || name[0] != 'r')
          return;
        uint32_t n = 0;
        for (size_t i = 1; i < name.size(); i++) {
          if (name[i] < '0' || name[i] > '9')
            return;
          n = n * 10 + uint32_t(name[i] - '0');
        }
        if (n >= 32 && n < 128 && !(name[1] == '0'))
          used[n] = any = true;
      });
      if (any) {
        std::string decl;
        for (uint32_t n = 32; n < 128; n++)
          if (used[n])
            decl += fmt::format("\tfloat4 r{} = vec4(0.0);\n", n);
        recompiler.out.insert(line_end + 1, decl);
      }
    }
  }

  out = {};
  out.hash = XXH3_64bits(container, size);
  out.pixel = recompiler.isPixelShader;
  out.glsl = TrimUnusedFunctions(MotionVectorPass(
      StageInterfacePasses(BoundTexturePass(recompiler.out, recompiler.isPixelShader), recompiler.isPixelShader),
      recompiler.isPixelShader));

  ShaderCacheEntry &e = out.entry;
  e.hash = out.hash;
  e.spirvSize = uint32_t(out.glsl.size());
  e.specConstantsMask = recompiler.specConstantsMask;
  e.vertexFetchMemoryMask = recompiler.vertexFetchMemoryMask;
  e.textureFetchMask = recompiler.textureFetchMask;
  std::memcpy(e.memExportConstants, recompiler.memExportConstants, sizeof(e.memExportConstants));
  std::memcpy(e.floatConstants, recompiler.floatConstants, sizeof(e.floatConstants));
  e.vertexInputCount = uint32_t(recompiler.vertexInputs.size());
  e.literalCount = uint32_t(recompiler.cbufLiterals.size());
  e.shaderFlags = recompiler.shaderFlags;

  out.inputs.reserve(recompiler.vertexInputs.size());
  for (const auto &v : recompiler.vertexInputs)
    out.inputs.push_back({v.usage, v.usageIndex, v.fetchIndex, v.format, v.flags, v.strideDwords, v.offsetDwords});
  out.literals.reserve(recompiler.cbufLiterals.size());
  for (const auto &l : recompiler.cbufLiterals)
    out.literals.push_back({l[0], {l[1], l[2], l[3], l[4]}});

  // The boolean specialization constants: "#define SPIRV_CROSS_CONSTANT_ID_<id> " lines (tw2de_bool_spec.h), as
  // tools/deko3d_shader_package.py read them.
  static constexpr std::string_view key = "#define SPIRV_CROSS_CONSTANT_ID_";
  for (size_t p = 0; (p = out.glsl.find(key, p)) != std::string::npos;) {
    p += key.size();
    uint32_t id = 0;
    size_t q = p;
    while (q < out.glsl.size() && out.glsl[q] >= '0' && out.glsl[q] <= '9')
      id = id * 10 + uint32_t(out.glsl[q++] - '0');
    if (q > p && q < out.glsl.size() && out.glsl[q] == ' ' && id >= 1000 && id < 1256)
      out.boolMask[(id - 1000) / 32] |= 1u << ((id - 1000) % 32);
  }
  return !out.glsl.empty();
}

}  // namespace renut::nxs
